const DICE = {
  white: { bg: "#f7f7f2", border: "#2d2d2d", pip: "#141414" },
  black: { bg: "#1a1a1a", border: "#444444", pip: "#f0f0e8" },
} as const;

type PipCount = 1 | 2 | 3 | 4 | 5 | 6;
type DiceFaceCfg = { pips: PipCount; bg: string; border: string; pip: string };

function diceFace(scheme: keyof typeof DICE, pips: PipCount): DiceFaceCfg {
  return { pips, ...DICE[scheme] };
}

function monoDice(
  scheme: keyof typeof DICE,
  top: PipCount,
  front: PipCount,
  side: PipCount,
  layout: Pick<DiceCfg, "size" | "rx" | "ry" | "pos">,
): DiceCfg {
  return {
    ...layout,
    top: diceFace(scheme, top),
    front: diceFace(scheme, front),
    side: diceFace(scheme, side),
  };
}

type DiceCfg = {
  size: number;
  rx: number;
  ry: number;
  top: DiceFaceCfg;
  front: DiceFaceCfg;
  side: DiceFaceCfg;
  pos: { [k: string]: string | number };
};

