const PIP_CELLS: Record<PipCount, [number, number][]> = {
  1: [[1, 1]],
  2: [[0, 0], [2, 2]],
  3: [[0, 0], [1, 1], [2, 2]],
  4: [[0, 0], [0, 2], [2, 0], [2, 2]],
  5: [[0, 0], [0, 2], [1, 1], [2, 0], [2, 2]],
  6: [[0, 0], [0, 2], [1, 0], [1, 2], [2, 0], [2, 2]],
};

function DiceFace({ face, transform }: { face: DiceFaceCfg; transform: string }) {
  const cells = PIP_CELLS[face.pips];
  return (
    <span
      style={{
        display: "block",
        position: "absolute",
        inset: 0,
        borderRadius: "18%",
        backgroundColor: face.bg,
        border: `1px solid ${face.border}`,
        transform,
        overflow: "hidden",
      }}
    >
      <span
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr 1fr",
          gridTemplateRows: "1fr 1fr 1fr",
          width: "100%",
          height: "100%",
          padding: "14%",
          boxSizing: "border-box",
        }}
      >
        {[0, 1, 2].flatMap((row) =>
          [0, 1, 2].map((col) => {
            const show = cells.some(([r, c]) => r === row && c === col);
            return (
              <span
                key={`${row}-${col}`}
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {show ? (
                  <span
                    style={{
                      width: "58%",
                      height: "58%",
                      borderRadius: "50%",
                      backgroundColor: face.pip,
                    }}
                  />
                ) : null}
              </span>
            );
          }),
        )}
      </span>
    </span>
  );
}

function Dice({ size, rx, ry, top, front, side, pos }: DiceCfg) {
  const half = `${size / 2}cqw`;
  return (
    <span
      style={{
        position: "absolute",
        width: `${size}cqw`,
        height: `${size}cqw`,
        perspective: "60cqw",
        zIndex: 0,
        pointerEvents: "none",
        ...pos,
      }}
    >
      <span
        style={{
          display: "block",
          position: "relative",
          width: "100%",
          height: "100%",
          transformStyle: "preserve-3d",
          transform: `rotateX(${rx}deg) rotateY(${ry}deg)`,
        }}
      >
        <DiceFace face={top} transform={`rotateX(90deg) translateZ(${half})`} />
        <DiceFace face={front} transform={`translateZ(${half})`} />
        <DiceFace face={side} transform={`rotateY(90deg) translateZ(${half})`} />
      </span>
    </span>
  );
}

